mod surface;
struct SmallOps<const P:i64,const D:i64>;
impl<const P:i64,const D:i64> surface::Ops for SmallOps<P,D>{type El=F<P,D>;fn c(&self,n:i64)->Self::El{F::c(n)}fn add(&self,a:&Self::El,b:&Self::El)->Self::El{*a+*b}fn mul(&self,a:&Self::El,b:&Self::El)->Self::El{*a * *b}}
fn surface_contract_small<const P:i64,const D:i64>(g:&Base<P,D>,q:&Base<P,D>,a:i64,b:i64,giants:&[(F<P,D>,F<P,D>,F<P,D>,F<P,D>)])->([F<P,D>;2],Value){let babies:Vec<_>=g.baby.iter().zip(&q.baby).skip(1).map(|(p,q)|{let(t,y)=p.unwrap();let(v,w)=q.unwrap();(t,v,y*w)}).collect();let mut k=1;while k*k<(g.b as usize){k+=1}surface::contract(&SmallOps::<P,D>,&F::c(a),&F::c(b),&babies,giants,k)}
fn surface_controls()->Value{
 let o=SmallOps::<211,210>;type FF=F<211,210>;let g=Some((FF::c(3),FF::c(33)));let bg=base(g,0,199);let babies:Vec<_>=bg.baby.iter().skip(1).map(|p|{let(t,y)=p.unwrap();(t,t,y*y)}).collect();let h=surface::branch_polynomial(&o,&FF::c(0),&FF::c(7));let one=surface::one(&o);
 let zero=surface::Four{p:std::array::from_fn(|_|std::collections::BTreeMap::new())};let mut simple=zero.clone();simple.p[0].insert((0,0),-babies[0].0);simple.p[0].insert((1,0),FF::c(1));simple.p[2].insert((0,0),FF::c(1));let mut other=simple.clone();other.p[0].insert((0,0),-babies[1].0);
 let mut eps=zero.clone();eps.p[2].insert((0,0),FF::c(1));let mut odd=zero.clone();odd.p[1].insert((0,0),FF::c(1));odd.p[3].insert((1,0),FF::c(1));let mut mixed=one.clone();mixed.p[1].insert((0,1),FF::c(2));mixed.p[2].insert((1,0),FF::c(3));mixed.p[3].insert((0,0),FF::c(5));
 let cases=vec![("empty",vec![]),("unit",vec![one.clone()]),("simple",vec![simple.clone()]),("same_root_twice",vec![simple.clone(),simple]),("distinct_roots",vec![other.clone(),{let mut s=other;s.p[0].insert((0,0),-babies[0].0);s}]),("zero",vec![zero]),("zero_then_unit",vec![eps,one]),("odd_square",vec![odd.clone(),odd]),("all_four_channels",vec![mixed.clone(),mixed])];let mut rows=vec![];let mut rejected=0;
 for(name,factors)in cases{let p=surface::balanced(&o,&h,&factors);let mut rootjets=vec![];let mut bad=false;for(t,v,w)in &babies{let actual=surface::evaluate(&o,&p,t,v,w);let mut expected=[FF::c(1),FF::c(0)];let mut wrong=expected;for f in &factors{let a=surface::evaluate(&o,f,t,v,w);expected=upd(expected,a);wrong=[wrong[0]*a[0],wrong[1]*a[1]]}assert_eq!(actual,expected);bad|=actual!=wrong;rootjets.push(actual.map(|x|x.code()));}if bad{rejected+=1}rows.push(json!({"name":name,"factors":factors.len(),"evaluated_jets":rootjets,"wrong_first_product_rejected":bad}));}assert!(rejected>0);json!({"all_checks_pass":true,"controls":rows,"wrong_product_rejections":rejected,"backend":"classical_sparse/direct evaluation"})
}
